                    "sql": "create or replace table prd_db.beardo.dwh_gross_contribution_Beardo as select * from ( with additional_sku_mapping as ( select m.*, coalesce(n.corrected_sku_weight,m.sku_weight_intermediate) sku_weight from ( select a.\"Product Code\" sku, max(ifnull(MRP,0)) mrp, div0(try_cast(substr(case when \"GST Tax Type Code\" = \'\' then \'0\' else trim(\"GST Tax Type Code\") end,11,2)as float),100) GST, sum(case when lower(type) = \'simple\' then 1 when lower(type) = \'bundle\' then (case when a.\"Component Quantity\" = \'\' then 0 else a.\"Component Quantity\"::float end) end) WH_units, sum(case when lower(type) = \'simple\' then (a.\"Weight (gms)\"::float) when lower(type) = \'bundle\' then b.component_weight*(case when a.\"Component Quantity\" = \'\' then 0 else a.\"Component Quantity\"::float end) end) sku_weight_intermediate, sum(case when b.component_weight <= 500 then 5.5*ifnull((case when a.\"Component Quantity\" = \'\' then 0 else a.\"Component Quantity\"::float end),1) when b.component_weight > 500 and b.component_weight <=1000 then 11*ifnull((case when a.\"Component Quantity\" = \'\' then 0 else a.\"Component Quantity\"::float end),1) when b.component_weight >1000 then 16.5*ifnull((case when a.\"Component Quantity\" = \'\' then 0 else a.\"Component Quantity\"::float end),1) end) warehousing_cost_sku, case when WH_units = 1 then 7 when WH_units > 1 then (WH_units+1)*7 end unit_emiza_cost from datalake_db.beardo.mst_unicommerce_item_master a left join ( select msm.\"Product Code\" child_sku, \"Weight (gms)\"::float component_weight from datalake_db.beardo.mst_unicommerce_item_master msm where lower(msm.type) = \'simple\' ) b on case when a.\"Component Product Code\" = \'\' then a.\"Product Code\" else a.\"Component Product Code\" end = b.child_sku group by 1,3 ) m left join datalake_db.beardo.mst_corrected_weights_for_volume n on n.\"Product Code\" = m.sku ) , orders as ( select * from prd_db.beardo.dwh_SHOPIFY_FACT_ITEMS where order_name not in (select distinct ordeR_name from prd_db.beardo.dwh_SHOPIFY_FACT_ITEMS where lower(tags) like \'%hypd%\' and total_sales in (0,0.01)) ), new_cogs as ( select \"SKU Code\" sku, cast(replace(\"New cogs\",\',\',\'\') as float) cogs, cast(replace(\"OLD COGS\",\',\',\'\') as float) old_cogs from datalake_db.beardo.beardo_gs_final_cogs qualify row_number() over (partition by \"SKU Code\" order by 1) = 1 ) select order_timestamp, order_id, ordeR_name, order_status, payment_gateway_mapped payment_method, mrp_sales, total_sales, total_discount, tax, shipping_price_without_tax, div0(total_discount,mrp_sales) discount_percent, NR NR, COGS as total_COGS, Gokwik_charge, ceil(div0(WH_units_for_order,4))*4 + 1.5 spm_cost, case when lower(expected_warehouse) like \'%zed%\' then 0 when Expected_Warehouse is null then 0 else warehousing_cost_line_item + 6.25 end warehousing_cost, case when lower(payment_gateway_mapped) = \'prepaid\' then (case when expected_zone = \'A\' then ceil(div0(order_weight+70,500))*25 when expected_zone = \'B\' then ceil(div0(order_weight+70,500))*32 when expected_zone = \'C\' then ceil(div0(order_weight+70,500))*42 when expected_zone = \'D\' then ceil(div0(order_weight+70,500))*48 when expected_zone = \'E\' then ceil(div0(order_weight+70,500))*54 when expected_zone is null then ceil(div0(order_weight+70,500))*48 end) when lower(payment_gateway_mapped) = \'cod\' then (case when expected_zone = \'A\' then ceil(div0(order_weight+70,500))*25 when expected_zone = \'B\' then ceil(div0(order_weight+70,500))*32 when expected_zone = \'C\' then ceil(div0(order_weight+70,500))*42 when expected_zone = \'D\' then ceil(div0(order_weight+70,500))*48 when expected_zone = \'E\' then ceil(div0(order_weight+70,500))*54 when expected_zone is null then ceil(div0(order_weight+70,500))*48 end) + 30 end as logistics_cost, common_expense_finance, null as cancellations, ifnull(NR,0) - ifnull(cancellations,0) - ifnull(COGS,0) - ifnull(warehousing_cost,0) - ifnull(common_expense_finance,0) - ifnull(spm_cost,0) - ifnull(logistics_cost,0) as GC, div0(GC,NR) GC_percent, discount_code, product_list, ceil(div0(order_weight+70,500)) weight_slab, expected_zone, expected_warehouse, GC_percent*100 GC_filter, order_timestamp::string timestamped_date, WH_units_for_order, order_weight from ( select order_timestamp, o.order_id, o.ordeR_name, o.order_status as order_status, discount_code, listagg(product_name, \', \') product_list, sum(o.total_sales) total_Sales, sum(asm.mrp*o.quantity) mrp_sales, sum(asm.mrp*o.quantity - (o.total_sales)) total_discount, sum(ifnull(o.total_sales,0)) - sum(div0(ifnull(o.total_sales,0),1+ifnull(asm.gst,0))) tax, sum(div0(ifnull(o.shipping_price,0),1.18)) shipping_price_without_tax, sum(div0(ifnull(o.total_sales,0),(1+ifnull(asm.gst,0)))) NR, ifnull(sum(case when new_cogs.cogs is null then cast(replace(scm.COGS, \',\', \'\') as float) else new_cogs.cogs end * o.quantity ),sum(asm.mrp * o.quantity) * 0.15) as COGS, sum(case when lower(payment_gateway_mapped) = \'prepaid\' then o.total_sales*0.01 when lower(payment_gateway_mapped) = \'cod\' then o.total_sales*0.015 end) Gokwik_charge, sum(case when lower(ExpectedWarehouse) like \'%zed%\' then 0 when ExpectedWarehouse is null then 0 else (asm.unit_emiza_cost*o.quantity) end) warehousing_cost_line_item, sum(asm.unit_emiza_cost) unit_emiza_cost, sum(o.quantity) quantity, max(expectedwarehouse) expected_warehouse, max(pezm.expectedzone) expected_zone, max(payment_gateway_mapped) payment_gateway_mapped, sum(asm.mrp*o.quantity*0.008) common_expense_finance, sum(asm.WH_units*o.quantity) WH_units_for_order, sum(asm.sku_weight*o.quantity) order_weight from orders o left join additional_sku_mapping asm on o.sku = asm.sku left join datalake_db.beardo.mst_sku_cogs_map scm on o.sku = scm.\"SKU Code\" left join new_cogs on lower(o.sku) = lower(new_cogs.sku) left join datalake_db.beardo.mst_pincode_expectedwarehouse_map pewm on pewm.pincode = o.pincode left join datalake_db.beardo.mst_pincode_expectedzone_map pezm on pezm.pincode = o.pincode group by 1,2,3,4,5 )) where ordeR_timestamp::date <=\'2024-04-30\' union all select * from ( with additional_sku_mapping as ( select m.*, coalesce(n.corrected_sku_weight,m.sku_weight_intermediate) sku_weight from ( select a.\"Product Code\" sku, max(ifnull(MRP,0)::float) mrp, div0(try_cast(substr(case when \"GST Tax Type Code\" = \'\' then \'0\' else trim(\"GST Tax Type Code\") end,11,2)as float),100) GST, sum(case when lower(type) = \'simple\' then 1 when lower(type) = \'bundle\' then (case when a.\"Component Quantity\" = \'\' then 0 else a.\"Component Quantity\"::float end) end) WH_units, sum(case when lower(type) = \'simple\' then a.\"Weight (gms)\"::float when lower(type) = \'bundle\' then b.component_weight*(case when a.\"Component Quantity\" = \'\' then 0 else a.\"Component Quantity\"::float end) end) sku_weight_intermediate, sum(case when b.component_weight <= 500 then 5.5*ifnull((case when a.\"Component Quantity\" = \'\' then 0 else a.\"Component Quantity\"::float end),1) when b.component_weight > 500 and b.component_weight <=1000 then 11*ifnull((case when a.\"Component Quantity\" = \'\' then 0 else a.\"Component Quantity\"::float end),1) when b.component_weight >1000 then 16.5*ifnull((case when a.\"Component Quantity\" = \'\' then 0 else a.\"Component Quantity\"::float end),1) end) warehousing_cost_sku, case when WH_units = 1 then 7 when WH_units > 1 then (WH_units+1)*7 end unit_emiza_cost from datalake_db.beardo.mst_unicommerce_item_master a left join ( select msm.\"Product Code\" child_sku, \"Weight (gms)\"::float component_weight from datalake_db.beardo.mst_unicommerce_item_master msm where lower(msm.type) = \'simple\' ) b on case when a.\"Component Product Code\" = \'\' then a.\"Product Code\" else a.\"Component Product Code\" end = b.child_sku group by 1,3 ) m left join datalake_db.beardo.mst_corrected_weights_for_volume n on n.\"Product Code\" = m.sku ) , orders as ( select * from prd_db.beardo.dwh_SHOPIFY_FACT_ITEMS where order_name not in (select distinct ordeR_name from prd_db.beardo.dwh_SHOPIFY_FACT_ITEMS where lower(tags) like \'%hypd%\' and total_sales in (0,0.01)) ), new_cogs as ( select \"SKU Code\" sku, cast(replace(\"New cogs\",\',\',\'\') as float) cogs, cast(replace(\"OLD COGS\",\',\',\'\') as float) old_cogs from datalake_db.beardo.beardo_gs_final_cogs qualify row_number() over (partition by \"SKU Code\" order by 1) = 1 ) select order_timestamp, order_id, ordeR_name, order_status, payment_gateway_mapped payment_method, mrp_sales, total_sales, total_discount, tax, shipping_price_without_tax, div0(total_discount,mrp_sales) discount_percent, m.NR NR, COGS as total_COGS, ifnull(mrp_sales,0)*r.gokwik_charge_factor as Gokwik_charge, ifnull(mrp_sales,0)*s.spm_cost_factor spm_cost, ifnull(mrp_sales,0)*p.warehouse_cost_factor warehousing_cost, ifnull(mrp_sales,0)*o.shipping_factor logistics_cost, ifnull(mrp_sales,0)*Q.common_expense_finance_factor common_expense_finance, cancellations, ifnull(m.NR,0) - ifnull(COGS,0) - ifnull(ifnull(mrp_sales,0)*p.warehouse_cost_factor,0) - ifnull(ifnull(mrp_sales,0)*Q.common_expense_finance_factor,0) - ifnull(ifnull(mrp_sales,0)*s.spm_cost_factor,0) - ifnull(ifnull(mrp_sales,0)*o.shipping_factor,0) as GC, div0(GC,m.NR ) GC_percent, discount_code, product_list, ceil(div0(order_weight+70,500)) weight_slab, expected_zone, expected_warehouse, GC_percent*100 GC_filter, order_timestamp::string timestamped_date, WH_units_for_order, order_weight from ( select order_timestamp, o.order_id, ordeR_name, o.order_status as order_status, discount_code, listagg(product_name, \', \') product_list, sum(wh_units) wh_units, sum (warehousing_cost_sku * o.quantity) warehousing_cost, sum(o.total_sales) total_Sales, sum(asm.mrp*o.quantity) mrp_sales, sum(asm.mrp*o.quantity - (o.total_sales)) total_discount, sum(ifnull(o.total_sales,0)) - sum(div0(ifnull(o.total_sales,0),1+ifnull(asm.gst,0))) tax, sum(div0(ifnull(o.shipping_price,0),1.18)) shipping_price_without_tax, sum(div0(ifnull(o.total_sales,0)*n.cancellations_factor,1+ifnull(asm.gst,0))) cancellations, sum(div0(ifnull(o.total_sales,0),(1+ifnull(asm.gst,0)))) - sum(div0(o.total_sales*n.cancellations_factor,1+ifnull(asm.gst,0))) NR, ifnull(sum(case when new_cogs.cogs is null then cast(replace(scm.COGS, \',\', \'\') as float) else new_cogs.cogs end * o.quantity ), sum(asm.mrp * o.quantity) * 0.15) as COGS, sum(case when lower(payment_gateway_mapped) = \'prepaid\' then o.total_sales*0.01 when lower(payment_gateway_mapped) = \'cod\' then o.total_sales*0.015 end) Gokwik_charge, sum(case when lower(ExpectedWarehouse) like \'%zed%\' then 0 when ExpectedWarehouse is null then 0 else (asm.unit_emiza_cost*o.quantity) end) warehousing_cost_line_item, sum(asm.unit_emiza_cost) unit_emiza_cost, sum(o.quantity) quantity, max(expectedwarehouse) expected_warehouse, max(pezm.expectedzone) expected_zone, max(payment_gateway_mapped) payment_gateway_mapped, sum(asm.mrp*o.quantity*0.008) common_expense_finance, sum(asm.WH_units*o.quantity) WH_units_for_order, sum(asm.sku_weight*o.quantity) order_weight from orders o left join additional_sku_mapping asm on o.sku = asm.sku left join datalake_db.beardo.mst_sku_cogs_map scm on o.sku = scm.\"SKU Code\" left join new_cogs on lower(o.sku) = lower(new_cogs.sku) left join datalake_db.beardo.mst_pincode_expectedwarehouse_map pewm on pewm.pincode = o.pincode left join datalake_db.beardo.mst_pincode_expectedzone_map pezm on pezm.pincode = o.pincode left join (select month, replace(factor,\'%\',\'\')/100 Cancellations_factor from datalake_db.beardo.mst_pandlassumptions where metric = \'Cancellations\') n on date_trunc(month, o.order_timestamp) = n.month group by 1,2,3,4,5 ) m left join (select month, replace(factor,\'%\',\'\')/100 Shipping_factor from datalake_db.beardo.mst_pandlassumptions where metric = \'Shipping\') o on date_trunc(month, m.order_timestamp) = o.month left join (select month, replace(factor,\'%\',\'\')/100 Warehouse_Cost_factor from datalake_db.beardo.mst_pandlassumptions where metric = \'Warehouse Cost\') p on date_trunc(month, m.order_timestamp) = p.month left join (select month, replace(factor,\'%\',\'\')/100 Common_Expense_Finance_factor from datalake_db.beardo.mst_pandlassumptions where metric = \'Common Expense Finance\') q on date_trunc(month, m.order_timestamp) = q.month left join (select month, replace(factor,\'%\',\'\')/100 Gokwik_Charge_factor from datalake_db.beardo.mst_pandlassumptions where metric = \'Gokwik Charge\') r on date_trunc(month, m.order_timestamp) = r.month left join (select month, replace(factor,\'%\',\'\')/100 SPM_Cost_factor from datalake_db.beardo.mst_pandlassumptions where metric = \'SPM Cost\') s on date_trunc(month, m.order_timestamp) = s.month ) where ordeR_timestamp::date >=\'2024-05-01\' ; create or replace table prd_db.beardo.dwh_gross_contribution_day_level_Beardo as SELECT order_timestamp::Date AS date, payment_method, weight_slab, expected_zone, expected_warehouse, COUNT(DISTINCT ordeR_id) AS orders, SUM(IFNULL(mrp_sales, 0)) AS mrp_sales, SUM(IFNULL(total_sales, 0)) AS total_sales, SUM(IFNULL(total_discount, 0)) AS total_discount, SUM(IFNULL(NR, 0)) AS NR, SUM(IFNULL(NR, 0) * (1 - y.return_rate)) AS expected_NR, SUM(IFNULL(total_cogs, 0)) AS total_cogs, SUM(IFNULL(total_cogs, 0) * (1 - y.return_rate)) AS expected_total_cogs, SUM(IFNULL(gokwik_charge, 0)) AS gokwik_charge, SUM(IFNULL(spm_cost, 0)) AS spm_cost, SUM(IFNULL(warehousing_cost, 0)) AS warehousing_cost, SUM(IFNULL(warehousing_cost, 0) + 6 * ifnull(WH_units_for_order,0) * IFNULL(y.return_rate, 0)) AS expected_warehousing_cost, SUM(IFNULL(logistics_cost, 0)) AS logistics_cost, SUM(CASE WHEN lower(payment_method) = \'prepaid\' THEN IFNULL(logistics_cost, 0) * (1 + IFNULL(y.return_rate, 0)) else (IFNULL(logistics_cost, 0) - 30) * (1 + IFNULL(y.return_rate, 0)) END) AS expected_logistics_cost, SUM(IFNULL(common_expense_finance, 0)) AS common_expense_finance, DIV0(300000 / DAY(LAST_DAY(order_timestamp::Date)), COUNT(*) OVER (PARTITION BY order_timestamp::Date ORDER BY 1)) AS daily_rent, SUM(IFNULL(NR, 0) * (1 - IFNULL(y.return_rate, 0))) - SUM(IFNULL(total_cogs, 0) * (1 - IFNULL(y.return_rate, 0))) - SUM(IFNULL(gokwik_charge, 0)) - SUM(IFNULL(warehousing_cost, 0) + 6 * IFNULL(y.return_rate, 0)) - SUM(IFNULL(common_expense_finance, 0)) - SUM(IFNULL(spm_cost, 0)) - SUM(CASE WHEN lower(payment_method) = \'prepaid\' THEN IFNULL(logistics_cost, 0) * (1 + IFNULL(y.return_rate, 0)) else (IFNULL(logistics_cost, 0) - 30) * (1 + IFNULL(y.return_rate, 0)) END) - ifnull(daily_rent,0) AS expected_GC, AVG(IFNULL(y.return_rate, 0)) AS return_rate FROM prd_db.beardo.dwh_gross_contribution_Beardo x LEFT JOIN ( SELECT a.date, b.return_rate FROM ( SELECT DISTINCT order_Date::Date AS date FROM prd_db.beardo.dwh_sales_consolidated ) a LEFT JOIN ( SELECT date_trunc(\'month\', order_date::Date) AS month, DIV0(COUNT(CASE WHEN LOWER(final_Status) = \'returned\' THEN ordeR_id END), COUNT(ordeR_id)) AS return_rate FROM prd_db.beardo.dwh_sales_consolidated WHERE shop_name = \'SHOPIFY_BEARDO\' GROUP BY date_trunc(\'month\', order_date::Date) ) b ON dateadd(month, -2, date_trunc(\'month\', a.date)) = b.month ) y ON x.order_timestamp::Date = y.Date GROUP BY 1, 2, 3, 4, 5; create or replace table prd_db.beardo.dwh_shopify_order_level_pnl as WITH additional_sku_mapping AS ( SELECT m.*, COALESCE(n.corrected_sku_weight, m.sku_weight_intermediate) AS sku_weight FROM ( SELECT a.\"Product Code\" AS sku, MAX(MRP::float) AS mrp, DIV0(TRY_CAST(SUBSTR(CASE WHEN \"GST Tax Type Code\" = \'\' THEN \'0\' ELSE TRIM(\"GST Tax Type Code\") END, 11, 2) AS float), 100) AS GST, SUM(CASE WHEN LOWER(type) = \'simple\' THEN 1 WHEN LOWER(type) = \'bundle\' THEN \"Component Quantity\"::float END) AS WH_units, SUM(CASE WHEN LOWER(type) = \'simple\' THEN a.\"Weight (gms)\"::float WHEN LOWER(type) = \'bundle\' THEN b.component_weight * a.\"Component Quantity\"::float END) AS sku_weight_intermediate, CASE WHEN WH_units = 1 THEN 7 WHEN WH_units > 1 THEN (WH_units + 1) * 7 END AS unit_emiza_cost FROM datalake_db.beardo.mst_unicommerce_item_master a LEFT JOIN ( SELECT msm.\"Product Code\" AS child_sku, \"Weight (gms)\"::float AS component_weight FROM datalake_db.beardo.mst_unicommerce_item_master msm WHERE LOWER(msm.type) = \'simple\' ) b ON a.\"Component Product Code\" = b.child_sku GROUP BY 1, 3 ) m LEFT JOIN datalake_db.beardo.mst_corrected_weights_for_volume n ON n.\"Product Code\" = m.sku ), daily_ad_revenue AS ( SELECT order_timestamp::date AS summary_date, final_utm_content AS ad_id, SUM(total_sales) AS daily_total_ad_revenue FROM prd_db.beardo.dwh_SHOPIFY_FACT_ITEMS GROUP BY 1, 2 ), daily_campaign_revenue AS ( SELECT order_timestamp::date AS summary_date, final_utm_campaign AS campaign_id, SUM(total_sales) AS daily_total_campaign_revenue FROM prd_db.beardo.dwh_SHOPIFY_FACT_ITEMS GROUP BY 1, 2 ), landing_page_views as ( select concat(\'HTTPS://BEARDO.IN\', upper(landingpage)) as landingpage, to_date(date,\'YYYYMMDD\') as date, sum(cast(sessions as int)) as sessions, sum(cast(engagedsessions as int)) as engaged_sessions, sum(cast(addtocarts as int)) as add_to_carts from datalake_db.beardo.ga4_beardo_landing_page_funnel_metrics group by 1,2 ), daily_page_sales AS ( SELECT order_timestamp::date AS order_date, upper(landingpageurl) AS landingpage, SUM(total_sales) AS total_page_sales_daily FROM prd_db.beardo.dwh_SHOPIFY_FACT_ITEMS GROUP BY 1, 2 ), daily_product_revenue AS ( SELECT order_timestamp::date AS order_date, upper(product_name) AS product_name, SUM(total_sales) AS total_product_sales_daily FROM prd_db.beardo.dwh_SHOPIFY_FACT_ITEMS GROUP BY 1, 2 ) SELECT s.order_timestamp::date AS order_date, s.order_name, s.line_item_id, s.final_utm_content AS ad_id, s.pincode, s.city, s.state, s.new_customer_flag, s.customer_id, s.order_status order_status, s.final_utm_source AS source, s.payment_gateway_mapped AS payment_method, s.sku, s.product_name, s.product_category, s.landingpageurl, coalesce(m.ad_name,mg.campaign_name) ad_name, s.quantity, s.total_sales, s.tax, s.line_item_sales, div0(s.total_sales, dps.total_page_sales_daily) * lpv.sessions AS distributed_sessions, div0(s.total_sales, dps.total_page_sales_daily) * lpv.engaged_sessions AS distributed_engaged_sessions, (case when lower(payment_gateway_mapped) = \'prepaid\' then s.total_sales*0.01 when lower(payment_gateway_mapped) = \'cod\' then s.total_sales*0.015 end) Gokwik_charge, (div0(ifnull(s.total_sales,0),(1+ifnull(asm.gst,0)))) - div0((s.total_sales*n.cancellations_factor),div0(s.total_sales,(div0(ifnull(s.total_sales,0),(1+ifnull(asm.gst,0)))))) as nr, div0(y.spm_cost,sum(s.quantity) over (partition by s.ordeR_name)) * s.quantity as spm_cost, div0(y.warehousing_cost,sum(s.quantity) over (partition by s.ordeR_name)) * s.quantity as warehousing_cost, div0(y.logistics_cost,sum(s.quantity) over (partition by s.ordeR_name)) * s.quantity as logistics_cost, div0(y.common_expense_finance,sum(s.quantity) over (partition by s.ordeR_name)) * s.quantity as common_expense_finance, ( CASE WHEN m.spend IS NOT NULL THEN (s.total_sales / NULLIF(rev.daily_total_ad_revenue, 0)) * m.spend ELSE (s.total_sales / NULLIF(camp_rev.daily_total_campaign_revenue, 0)) * mg.spend END ) AS spend, (asm.mrp * s.quantity) AS mrp_sales, ((asm.mrp * s.quantity) - s.total_sales) AS discount, (case when new_cogs.sku is null then cast(replace(scm.COGS, \',\', \'\') as float) else new_cogs.cogs end * s.quantity) AS cogs, s.shipping_price, (div0(s.total_sales, dpr.total_product_sales_daily) * ad_name_spends.spend) AS ad_product_spend, (div0(ifnull(s.total_sales,0)*n.cancellations_factor,1+ifnull(asm.gst,0))) cancellations, (div0(ifnull(s.total_sales,0),(1+ifnull(asm.gst,0)))) - div0((s.total_sales*n.cancellations_factor),div0(s.total_sales,(div0(ifnull(s.total_sales,0),(1+ifnull(asm.gst,0)))))) - div0((s.total_sales*n.cancellations_factor),div0(s.total_sales,(div0(ifnull(s.total_sales,0),(1+ifnull(asm.gst,0)))) - div0((s.total_sales*n.cancellations_factor),div0(s.total_sales,(div0(ifnull(s.total_sales,0),(1+ifnull(asm.gst,0)))))))) - ( (case when new_cogs.sku is null then cast(replace(scm.COGS, \',\', \'\') as float) else new_cogs.cogs end * s.quantity)) - 0 - (div0(y.warehousing_cost,sum(s.quantity) over (partition by s.ordeR_name)) * s.quantity) - (div0(y.common_expense_finance,sum(s.quantity) over (partition by s.ordeR_name)) * s.quantity) - (div0(y.logistics_cost,sum(s.quantity) over (partition by s.ordeR_name)) * s.quantity) as GC FROM prd_db.beardo.dwh_SHOPIFY_FACT_ITEMS s LEFT JOIN additional_sku_mapping asm ON s.sku = asm.sku LEFT JOIN daily_ad_revenue rev ON s.order_timestamp::date = rev.summary_date AND s.final_utm_content = rev.ad_id LEFT JOIN daily_campaign_revenue camp_rev ON s.order_timestamp::date = camp_rev.summary_date AND s.final_utm_campaign = camp_rev.campaign_id LEFT JOIN daily_page_sales dps ON s.order_timestamp::date = dps.order_date AND upper(s.landingpageurl) = dps.landingpage LEFT JOIN landing_page_views lpv ON s.order_timestamp::date = lpv.date AND upper(s.landingpageurl) = lpv.landingpage LEFT JOIN ( SELECT date::date as spend_date, CAST(CAST(ad_id AS INT) AS STRING) as spend_ad_id, MAX(regexp_replace(ad_name, \' +\', \' \')) as ad_name, sum(spend) as spend FROM prd_db.Beardo.dwh_MARKETING_CONSOLIDATED where upper(channel) = \'FACEBOOK\' GROUP BY 1, 2 ) m ON m.spend_ad_id = s.final_utm_content AND s.order_timestamp::date = m.spend_date LEFT JOIN daily_product_revenue dpr ON s.order_timestamp::date = dpr.order_date AND upper(s.product_name) = dpr.product_name LEFT JOIN ( SELECT date::date as spend_date, replace(CAST(SPLIT_PART(ad_name, \'|\', 1) as string),\'Beardo \',\'\') as ad_product_name, sum(spend) as spend FROM prd_db.Beardo.dwh_MARKETING_CONSOLIDATED where upper(channel) = \'FACEBOOK\' GROUP BY 1, 2 ) ad_name_spends ON upper(trim(ad_name_spends.ad_product_name)) = upper(trim(s.product_name)) AND s.order_timestamp::date = ad_name_spends.spend_date LEFT JOIN ( SELECT date::date as spend_date, CAST(CAST(campaign_id AS INT) AS STRING) as spend_campaign_id, MAX(campaign_name) as campaign_name, sum(spend) as spend FROM prd_db.Beardo.dwh_MARKETING_CONSOLIDATED where channel = \'GOOGLE\' GROUP BY 1, 2 ) mg ON mg.spend_campaign_id = s.final_utm_campaign AND s.order_timestamp::date = mg.spend_date LEFT JOIN ( SELECT \"SKU Code\", cogs FROM datalake_db.beardo.mst_sku_cogs_map QUALIFY ROW_NUMBER() OVER (PARTITION BY \"SKU Code\" ORDER BY 1) = 1 ) scm ON s.sku = scm.\"SKU Code\" LEFT JOIN ( select \"SKU Code\" sku, cast(replace(\"New cogs\",\',\',\'\') as float) cogs, cast(replace(\"OLD COGS\",\',\',\'\') as float) old_cogs from datalake_db.beardo.beardo_gs_final_cogs qualify row_number() over (partition by \"SKU Code\" order by 1) = 1 ) new_cogs on lower(s.sku) = lower(new_cogs.sku) left join (select * from prd_db.beardo.dwh_gross_contribution_Beardo) y on s.ordeR_name = y.ordeR_name left join (select month, replace(factor,\'%\',\'\')/100 Cancellations_factor from datalake_db.beardo.mst_pandlassumptions where metric = \'Cancellations\') n on date_trunc(month, s.order_timestamp) = n.month ; create or replace table prd_db.beardo.dwh_gross_contribution_product_Beardo as select * from ( with additional_sku_mapping as ( select m.*, coalesce(n.corrected_sku_weight,m.sku_weight_intermediate) sku_weight from ( select a.\"Product Code\" sku, max(MRP::float) mrp, div0(try_cast(substr(case when \"GST Tax Type Code\" = \'\' then \'0\' else trim(\"GST Tax Type Code\") end,11,2)as float),100) GST, sum(case when lower(type) = \'simple\' then 1 when lower(type) = \'bundle\' then \"Component Quantity\"::float end) WH_units, sum(case when lower(type) = \'simple\' then a.\"Weight (gms)\"::float when lower(type) = \'bundle\' then b.component_weight*a.\"Component Quantity\"::float end) sku_weight_intermediate, case when WH_units = 1 then 7 when WH_units > 1 then (WH_units+1)*7 end unit_emiza_cost from datalake_db.beardo.mst_unicommerce_item_master a left join ( select msm.\"Product Code\" child_sku, \"Weight (gms)\"::float component_weight from datalake_db.beardo.mst_unicommerce_item_master msm where lower(msm.type) = \'simple\' ) b on a.\"Component Product Code\" = b.child_sku group by 1,3 ) m left join datalake_db.beardo.mst_corrected_weights_for_volume n on n.\"Product Code\" = m.sku ) , sku_mapping as ( select distinct trim(upper(\"Product Code\")) as parent_sku, trim(upper(\"Component Product Code\")) as child_sku from datalake_db.beardo.beardo_product_item_master ), shopify_data as ( select * from prd_db.beardo.dwh_shopify_fact_items where order_name not in ( select distinct order_name from prd_db.beardo.dwh_shopify_fact_items where lower(tags) like \'%hypd%\' and total_sales in (0,0.01) ) ), unicommerce_data as ( select reference_code, sku, shipping_status, shippingpackagestatus, order_status from ( select distinct reference_code, sku, shipping_status, shippingpackagestatus, order_status, row_number() over (partition by reference_code, sku order by 1) rw from prd_db.beardo.dwh_unicommerce_fact_items where marketplace = \'SHOPIFY\' ) where rw = 1 ), shopify_expected_skus as ( select s.order_name, s.sku as shopify_sku, coalesce(m.child_sku, trim(upper(s.sku))) as expected_unicommerce_sku from shopify_data s left join sku_mapping m on trim(upper(s.sku)) = m.parent_sku ), shopify_to_uni_statuses as ( select se.order_name, se.shopify_sku, max(u.order_status) as order_status, max(u.shipping_status) as shipping_status, max(u.shippingpackagestatus) as shippingpackagestatus from shopify_expected_skus se left join unicommerce_data u on trim(replace(se.order_name, \'#\', \'\')) = trim(u.reference_code) and se.expected_unicommerce_sku = trim(upper(u.sku)) group by se.order_name, se.shopify_sku ), orders as ( select a.*, b.order_status oms_order_status, b.shipping_status, b.shippingpackagestatus from (select * from prd_db.beardo.dwh_SHOPIFY_FACT_ITEMS where order_name not in (select distinct ordeR_name from prd_db.beardo.dwh_SHOPIFY_FACT_ITEMS where lower(tags) like \'%hypd%\' and total_sales in (0,0.01)) ) a left join shopify_to_uni_statuses b on a.order_name = b.order_name and a.sku = b.shopify_sku ), new_cogs as ( select \"SKU Code\" sku, cast(replace(\"New cogs\",\',\',\'\') as float) cogs, cast(replace(\"OLD COGS\",\',\',\'\') as float) old_cogs from datalake_db.beardo.beardo_gs_final_cogs qualify row_number() over (partition by \"SKU Code\" order by 1) = 1 ) select order_timestamp, order_id, new_customer_flag, customer_id, sku, product_name, product_category, ordeR_name, pincode, city, order_status, shipping_status, shippingpackagestatus as shipping_package_status, final_utm_source, payment_gateway_mapped payment_method, mrp_sales, tax, tax_actual, (gross_sales_after_tax - tax_actual) as gross_sales, total_sales, line_item_sales, gross_sales_after_tax, total_discount, shipping_price, cancellations, div0(total_discount,mrp_sales) discount_percent, NR, COGS total_COGS, Gokwik_charge, ceil(div0(WH_units_for_order,4))*4 + 1.5 spm_cost, case when lower(expected_warehouse) like \'%zed%\' then 0 when Expected_Warehouse is null then 0 else warehousing_cost_line_item + 6.25 end warehousing_cost, case when lower(payment_gateway_mapped) = \'prepaid\' then (case when expected_zone = \'A\' then ceil(div0(order_weight+70,500))*25 when expected_zone = \'B\' then ceil(div0(order_weight+70,500))*32 when expected_zone = \'C\' then ceil(div0(order_weight+70,500))*42 when expected_zone = \'D\' then ceil(div0(order_weight+70,500))*48 when expected_zone = \'E\' then ceil(div0(order_weight+70,500))*54 when expected_zone is null then ceil(div0(order_weight+70,500))*48 end) when lower(payment_gateway_mapped) = \'cod\' then (case when expected_zone = \'A\' then ceil(div0(order_weight+70,500))*25 when expected_zone = \'B\' then ceil(div0(order_weight+70,500))*32 when expected_zone = \'C\' then ceil(div0(order_weight+70,500))*42 when expected_zone = \'D\' then ceil(div0(order_weight+70,500))*48 when expected_zone = \'E\' then ceil(div0(order_weight+70,500))*54 when expected_zone is null then ceil(div0(order_weight+70,500))*48 end) + 30 end as logistics_cost, common_expense_finance, NR - total_COGS - gokwik_charge - warehousing_cost - common_expense_finance - spm_cost - logistics_cost as GC, div0(GC,NR) GC_percent, discount_code, product_list, ceil(div0(order_weight+70,500)) weight_slab, expected_zone, expected_warehouse, GC_percent*100 GC_filter, order_timestamp::string timestamped_date, quantity from ( select order_timestamp, order_id, ordeR_name, o.pincode, o.city, new_customer_flag, coalesce(oms_order_Status, order_status) ordeR_status, shipping_Status, shippingpackagestatus, final_utm_source, o.sku, o.product_name, o.product_category, discount_code, o.customer_id, listagg(product_name, \', \') product_list, sum(shipping_price) shipping_price, sum(div0(ifnull(o.total_sales,0)*n.cancellations_factor,1+ifnull(asm.gst,0))) cancellations, sum(o.total_sales) total_Sales, sum(o.tax) tax, sum(o.tax_actual) tax_actual, sum(o.line_item_sales) line_item_sales, sum(o.gross_sales_after_tax) gross_sales_after_tax, sum(asm.mrp*o.quantity) mrp_sales, sum(asm.mrp*o.quantity - (o.total_sales)) total_discount, sum(div0(ifnull(o.total_sales,0),(1+ifnull(asm.gst,0))) ) NR, ifnull(sum(case when new_cogs.cogs is null then cast(replace(scm.COGS, \',\', \'\') as float) else new_cogs.cogs end * o.quantity ),sum(asm.mrp * o.quantity) * 0.15) as COGS, sum(case when lower(payment_gateway_mapped) = \'prepaid\' then o.total_sales*0.01 when lower(payment_gateway_mapped) = \'cod\' then o.total_sales*0.015 end) Gokwik_charge, sum(case when lower(ExpectedWarehouse) like \'%zed%\' then 0 when ExpectedWarehouse is null then 0 else (asm.unit_emiza_cost*o.quantity) end) warehousing_cost_line_item, sum(asm.unit_emiza_cost) unit_emiza_cost, sum(o.quantity) quantity, max(expectedwarehouse) expected_warehouse, max(pezm.expectedzone) expected_zone, max(payment_gateway_mapped) 