alake_db.beardo.beardo_gs_final_cogs qualify row_number() over (partition by \"SKU Code\" order by 1) = 1 ) select m.order_timestamp, m.order_id, m.new_customer_flag, m.customer_id, m.sku, m.product_name, m.product_category, m.ordeR_name, m.pincode, m.city, m.order_status, m.shipping_status, m.shippingpackagestatus as shipping_package_status, m.final_utm_source, m.payment_gateway_mapped payment_method, m.mrp_sales, m.tax, m.tax_actual, (m.gross_sales_after_tax - m.tax_actual) as gross_sales, m.total_sales, m.line_item_sales, m.gross_sales_after_tax, m.total_discount, m.shipping_price, m.cancellations, div0(m.total_discount,m.mrp_sales) discount_percent, m.NR - div0((m.total_sales*n.cancellations_factor),div0(m.total_sales,m.NR)) NR, m.COGS total_COGS, 0 as Gokwik_charge, div0(y.spm_cost,sum(m.quantity) over (partition by m.ordeR_name)) * m.quantity spm_cost, div0(y.warehousing_cost,sum(m.quantity) over (partition by m.ordeR_name)) * m.quantity warehousing_cost, div0(y.logistics_cost,sum(m.quantity) over (partition by m.ordeR_name)) * m.quantity logistics_cost, div0(y.common_expense_finance,sum(m.quantity) over (partition by m.ordeR_name)) * m.quantity common_expense_finance, m.NR - div0((m.total_sales*n.cancellations_factor),div0(m.total_sales,m.NR)) - m.cogs - 0 - (div0(y.warehousing_cost,sum(m.quantity) over (partition by m.ordeR_name)) * m.quantity) - (div0(y.common_expense_finance,sum(m.quantity) over (partition by m.ordeR_name)) * m.quantity) - (div0(y.spm_cost,sum(m.quantity) over (partition by m.ordeR_name)) * m.quantity) - (div0(y.logistics_cost,sum(m.quantity) over (partition by m.ordeR_name)) * m.quantity) as GC, div0(GC,m.NR - m.total_sales*n.cancellations_factor) GC_percent, m.discount_code, m.product_list, ceil(div0(m.order_weight+70,500)) weight_slab, m.expected_zone, m.expected_warehouse, GC_percent*100 GC_filter, m.order_timestamp::string timestamped_date, m.quantity from ( select order_timestamp, order_id, ordeR_name, o.pincode, o.city, new_customer